package kvhttp

import java.util.concurrent.ConcurrentSkipListMap

/** Thread-safe in-memory key-value store whose keys are kept in ascending order. */
class KvStore {
    private val entries = ConcurrentSkipListMap<String, ByteArray>()

    /** Stores [value] under [key]; returns `true` if the key was not present before. */
    fun put(key: String, value: ByteArray): Boolean = entries.put(key, value) == null

    operator fun get(key: String): ByteArray? = entries[key]

    /** Removes [key]; returns `true` if it was present. */
    fun delete(key: String): Boolean = entries.remove(key) != null

    /** All keys, sorted ascending. */
    fun keys(): List<String> = entries.keys.toList()
}

package kvhttp

import com.sun.net.httpserver.HttpExchange
import com.sun.net.httpserver.HttpServer
import java.io.InputStream
import java.net.InetAddress
import java.net.InetSocketAddress
import java.util.concurrent.Executors
import kotlin.system.exitProcess

const val MAX_VALUE_BYTES = 1 shl 20

fun main(args: Array<String>) {
    val port = args.singleOrNull()?.toIntOrNull()?.takeIf { it in 1..65535 } ?: run {
        System.err.println("usage: app <port>")
        exitProcess(2)
    }
    val router = Router(KvStore())
    val server = HttpServer.create(InetSocketAddress(InetAddress.getLoopbackAddress(), port), 1024)
    server.executor = Executors.newVirtualThreadPerTaskExecutor()
    server.createContext("/") { exchange -> exchange.use { serve(it, router) } }
    server.start()
}

private fun serve(exchange: HttpExchange, router: Router) {
    val response = try {
        val body = readBody(exchange)
        if (body == null) {
            Response.text(413, "value too large")
        } else {
            router.handle(exchange.requestMethod, exchange.requestURI.rawPath, body)
        }
    } catch (e: Exception) {
        System.err.println("request failed: $e")
        Response.text(500, "internal error")
    }
    send(exchange, response)
}

/** Reads the request body, or returns `null` if it exceeds [MAX_VALUE_BYTES]. */
private fun readBody(exchange: HttpExchange): ByteArray? {
    val declared = exchange.requestHeaders.getFirst("Content-Length")?.trim()?.toLongOrNull()
    if (declared != null && declared > MAX_VALUE_BYTES) return null
    return exchange.requestBody.use { it.readAtMost(MAX_VALUE_BYTES) }
}

private fun InputStream.readAtMost(limit: Int): ByteArray? {
    val bytes = readNBytes(limit)
    return if (read() == -1) bytes else null
}

private fun send(exchange: HttpExchange, response: Response) {
    response.contentType?.let { exchange.responseHeaders["Content-Type"] = it }
    val body = response.body
    // A length of -1 tells HttpServer there is no body; it then emits Content-Length: 0 (none for 204).
    val length = if (body.isEmpty()) -1L else body.size.toLong()
    exchange.sendResponseHeaders(response.status, length)
    if (body.isNotEmpty()) exchange.responseBody.use { it.write(body) }
}

package kvhttp

/** A fully materialised HTTP response. */
class Response(
    val status: Int,
    val body: ByteArray = ByteArray(0),
    val contentType: String? = null,
) {
    companion object {
        fun text(status: Int, text: String = "") =
            Response(status, text.encodeToByteArray(), if (text.isEmpty()) null else "text/plain; charset=utf-8")

        fun json(status: Int, json: String) =
            Response(status, json.encodeToByteArray(), "application/json")
    }
}

private val KEY_PATTERN = Regex("[A-Za-z0-9_-]{1,64}")

fun isValidKey(key: String): Boolean = KEY_PATTERN.matches(key)

/** Maps requests onto [store] operations. Pure with respect to I/O, so it is easy to test. */
class Router(private val store: KvStore) {

    fun handle(method: String, path: String, body: ByteArray): Response = when {
        path == "/health" -> when (method) {
            "GET" -> Response.text(200, "ok")
            else -> methodNotAllowed()
        }
        path == "/kv" -> when (method) {
            "GET" -> Response.json(200, store.keys().joinToString(",", "[", "]") { "\"$it\"" })
            else -> methodNotAllowed()
        }
        path.startsWith(KV_PREFIX) -> handleKey(method, path.removePrefix(KV_PREFIX), body)
        else -> Response.text(404, "not found")
    }

    private fun handleKey(method: String, key: String, body: ByteArray): Response {
        if (!isValidKey(key)) return Response.text(400, "invalid key")
        return when (method) {
            "GET" -> store[key]?.let { Response(200, it, "application/octet-stream") } ?: notFound()
            "PUT" -> Response(if (store.put(key, body)) 201 else 200)
            "DELETE" -> if (store.delete(key)) Response(204) else notFound()
            else -> methodNotAllowed()
        }
    }

    private fun notFound() = Response.text(404, "not found")

    private fun methodNotAllowed() = Response.text(405, "method not allowed")

    private companion object {
        const val KV_PREFIX = "/kv/"
    }
}
